    if (rest.isEmpty) {
      _writer('Error: run requires a job name or a JSON config file.');
      _writer('Usage: dmtools run <json-file> [encoded] [--key value ...]');
      return 1;
    }
    final resolver = _packResolver ?? AgentPackResolver();
    final pinned = _pinnedPackFor(rest, resolver);
